    if (insert) {
      script.push({ op: 'insert', line: b[--y] });
    } else {
      script.push({ op: 'delete', line: a[--x] });
    }
  }
  while (x > 0) {
    script.push({ op: 'equal', line: a[--x] });
  }
  script.reverse();

  // A shortest path can interleave inserts and deletes. Stable partition each
  // changed region without moving edits across any equal entry.
  const inserts = [];
  for (let start = 0; start < script.length;) {
    if (script[start].op === 'equal') {
      start++;
      continue;
    }
    let end = start;
    let write = start;
    while (end < script.length && script[end].op !== 'equal') {
      const entry = script[end++];
      if (entry.op === 'delete') {
        script[write++] = entry;
      } else {
        inserts.push(entry);
      }
    }
    for (const entry of inserts) {
      script[write++] = entry;
    }
