'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const row = new Array(b.length + 1).fill(0);
  for (const line of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const above = row[j];
      row[j] = line === b[j - 1] ? diagonal + 1 : Math.max(row[j], row[j - 1]);
      diagonal = above;
    }
  }
  return row[b.length];
}

function checkScript(a, b) {
  const script = diffLines(a, b);
  assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
  assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
  assert.equal(script.filter(e => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
  let inserted = false;
  for (const entry of script) {
    assert.ok(['equal', 'insert', 'delete'].includes(entry.op));
    if (entry.op === 'equal') inserted = false;
    if (entry.op === 'insert') inserted = true;
    if (entry.op === 'delete') assert.equal(inserted, false);
  }
  assert.deepEqual(diffLines(a, b), script);
}

test('exhaustive repeated/empty-line minimality and patch roundtrips', () => {
  const inputs = [Object.freeze([])];
  let level = [[]];
  for (let length = 1; length <= 4; length++) {
    level = level.flatMap(a => ['', 'a', 'b'].map(line => Object.freeze([...a, line])));
    inputs.push(...level);
  }
  for (const a of inputs) {
    for (const b of inputs) {
      checkScript(a, b);
      for (const context of [0, 1, 2, 3]) {
        const hunks = unifiedHunks(a, b, { context });
        for (const hunk of hunks) {
          Object.freeze(hunk.lines);
          Object.freeze(hunk);
        }
        Object.freeze(hunks);
        assert.deepEqual(applyHunks(a, hunks), b);
      }
    }
  }
});

test('zero-range coordinates, exact prefixes, touching contexts and offsets', () => {
  for (const position of [0, 1, 3]) {
    const a = ['a', 'b', 'c'];
    const b = [...a.slice(0, position), '+new', ...a.slice(position)];
    assert.deepEqual(unifiedHunks(a, b, { context: 0 }), [{
      oldStart: position, oldLines: 0, newStart: position + 1, newLines: 1, lines: ['++new'],
    }]);
    assert.deepEqual(unifiedHunks(b, a, { context: 0 }), [{
      oldStart: position + 1, oldLines: 1, newStart: position, newLines: 0, lines: ['-+new'],
    }]);
