        assert.deepEqual(applyHunks(a, hunks), b);
      }
    }
  }
});

test('zero-range coordinates, exact prefixes, touching contexts and offsets', () => {
  for (const position of [0, 1, 3]) {
    const a = ['a', 'b', 'c'];
    const b = [...a.slice(0, position), '+new', ...a.slice(position)];
    assert.deepEqual(unifiedHunks(a, b, { context: 0 }), [{
      oldStart: position, oldLines: 0, newStart: position + 1, newLines: 1, lines: ['++new'],
    }]);
    assert.deepEqual(unifiedHunks(b, a, { context: 0 }), [{
      oldStart: position + 1, oldLines: 1, newStart: position, newLines: 0, lines: ['-+new'],
    }]);
  }
  const a = ['old1', 'gap1', 'gap2', 'old2'];
  const b = ['new1', 'gap1', 'gap2', 'new2'];
  assert.deepEqual(unifiedHunks(a, b, { context: 1 }), [{
    oldStart: 1, oldLines: 4, newStart: 1, newLines: 4,
    lines: ['-old1', '+new1', ' gap1', ' gap2', '-old2', '+new2'],
  }]);
  const separated = ['old1', 'gap1', 'gap2', 'gap3', 'old2'];
  const replacement = ['new1', 'gap1', 'gap2', 'gap3', 'new2'];
  assert.deepEqual(unifiedHunks(separated, replacement, { context: 1 }), [
    { oldStart: 1, oldLines: 2, newStart: 1, newLines: 2, lines: ['-old1', '+new1', ' gap1'] },
    { oldStart: 4, oldLines: 2, newStart: 4, newLines: 2, lines: [' gap3', '-old2', '+new2'] },
  ]);
  const prefixes = ['', '+leading', '-leading', ' leading', 'tail'];
  const changed = ['+added', '', '+leading', ' leading', 'tail', '-added'];
  assert.deepEqual(applyHunks(prefixes, unifiedHunks(prefixes, changed)), changed);
  const offsetOld = ['a', 'b', 'c', 'd', 'e', 'f'];
  const offsetNew = ['x', 'a', 'b', 'd', 'e', 'y', 'f', 'z'];
  assert.deepEqual(applyHunks(offsetOld, unifiedHunks(offsetOld, offsetNew, { context: 0 })), offsetNew);
  assert.deepEqual(unifiedHunks(prefixes, prefixes), []);
  const copy = applyHunks(prefixes, []);
  assert.deepEqual(copy, prefixes);
  assert.notEqual(copy, prefixes);
});

test('malformed, mismatching, overlapping and out-of-order hunks report their index', () => {
  const a = Object.freeze(['a', 'b', 'c']);
  const valid = { oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: ['-a', '+x'] };
  const invalid = [
    null, {}, { ...valid, oldStart: 0 }, { ...valid, oldStart: 5 },
    { ...valid, oldStart: 1.5 }, { ...valid, oldLines: -1 },
    { ...valid, oldLines: 2 }, { ...valid, newLines: 2 },
    { ...valid, newStart: 2 }, { ...valid, newStart: NaN },
    { ...valid, lines: ['-wrong', '+x'] },
    { ...valid, lines: [' wrong'] }, { ...valid, lines: ['?a'] },
    { ...valid, lines: [''] }, { ...valid, lines: [null] },
    { ...valid, lines: 'a' },
    { oldStart: 3, oldLines: 2, newStart: 3, newLines: 0, lines: ['-c', '-d'] },
  ];
  for (const hunk of invalid) {
    assert.throws(() => applyHunks(a, [hunk]), /hunk 0 does not apply/);
  }
  assert.throws(() => applyHunks(a, [valid, valid]), /hunk 1 does not apply/);
  const last = { oldStart: 3, oldLines: 1, newStart: 3, newLines: 1, lines: ['-c', '+z'] };
  assert.throws(() => applyHunks(a, [last, valid]), /hunk 1 does not apply/);
  const wrongOffset = { oldStart: 3, oldLines: 0, newStart: 4, newLines: 1, lines: ['+z'] };
  const insert = { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] };
  assert.throws(() => applyHunks(a, [insert, wrongOffset]), /hunk 1 does not apply/);
});

test('small edits to unique and repetitive 20,000-line files stay below one second', () => {
  for (const repetitive of [false, true]) {
    const a = Array.from({ length: 20000 }, (_, i) => repetitive ? `repeat ${i % 3}` : `line ${i}`);
    const b = a.slice();
    b.splice(100, 1, 'replacement');
    b.splice(10000, 0, '+insert');
    b.splice(18000, 1);
    const start = performance.now();
    const script = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    const result = applyHunks(a, hunks);
    const milliseconds = performance.now() - start;
    assert.deepEqual(result, b);
    assert.equal(script.filter(e => e.op !== 'equal').length, 4);
    assert.ok(milliseconds < 1000, `${milliseconds}ms`);
    console.log(`${repetitive ? 'repetitive' : 'unique'} 20,000-line diff + hunks + apply: ${milliseconds.toFixed(2)}ms`);
  }
});
